"""Strategy Lead synthesis of completed A–O research. No new observations generated."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'data'
research = {p.stem: json.loads(p.read_text()) for p in DATA.glob('*.json')}
source_index = {}
for dataset in research.values():
    if isinstance(dataset, dict):
        for source in dataset.get('sources', []):
            source_index[source['id']] = source
for source in research.get('sources', []):
    source_index[source['id']] = source

def check(label, met, evidence, *source):
    return dict(label=label, met=met, evidence=evidence, source=list(source))

def score(id, name, scope, confidence, checks):
    return dict(id=id, name=name, score=25*sum(c['met'] for c in checks), confidence=confidence,
                classification='INFERRED', scope=scope, criteria=checks,
                source=list(dict.fromkeys(s for c in checks for s in c['source'])))

