def walk_refs(value):
    if isinstance(value,dict):
        for key,child in value.items():
            if key=='source':
                assert isinstance(child,list),child
                for sid in child: assert sid in source_index,f'Unknown source: {sid}'
            else: walk_refs(child)
    elif isinstance(value,list):
        for child in value: walk_refs(child)

for name,value in [('strategy',strategy),('opportunities',opportunities),('roadmap',roadmap)]:
    walk_refs(value)
    (DATA/(name+'.json')).write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
